html[lang^="es"] .solandvolt-product-reassurance .sv-reassurance-item:has(a[href^="mailto:"]),
html[lang^="es"] .solandvolt-product-reassurance .sv-reassurance-item:first-child strong,
html[lang^="es"] .solandvolt-product-reassurance .sv-reassurance-item:has(a[href^="mailto:"]) strong,
html[lang^="es"] .solandvolt-product-reassurance .sv-reassurance-item:has(a[href^="mailto:"]) a { font-size: 0; }
html[lang^="es"] .solandvolt-product-reassurance .sv-reassurance-item:first-child .sv-check,
html[lang^="es"] .solandvolt-product-reassurance .sv-reassurance-item:has(a[href^="mailto:"]) .sv-check,
html[lang^="es"] .solandvolt-product-reassurance .sv-reassurance-item:first-child strong::before,
html[lang^="es"] .solandvolt-product-reassurance .sv-reassurance-item:first-child strong::after,
html[lang^="es"] .solandvolt-product-reassurance .sv-reassurance-item:has(a[href^="mailto:"]) strong::before,
html[lang^="es"] .solandvolt-product-reassurance .sv-reassurance-item:has(a[href^="mailto:"]) strong::after,
html[lang^="es"] .solandvolt-product-reassurance .sv-reassurance-item:has(a[href^="mailto:"]) a::after { font-size: var(--wp--preset--font-size--large); }
html[lang^="es"] .solandvolt-product-reassurance .sv-reassurance-item:first-child strong::before { content: "\00a0 Envío gratuito de 60 € a 350 €"; }
html[lang^="es"] .solandvolt-product-reassurance .sv-reassurance-item:first-child strong::after { content: " a Francia y España; por encima, transporte según el peso"; font-weight: 400; }
html[lang^="es"] .solandvolt-product-reassurance .sv-reassurance-item:has(a[href^="mailto:"]) strong::before { content: "\00a0 Instalación posible con presupuesto previo"; }
html[lang^="es"] .solandvolt-product-reassurance .sv-reassurance-item:has(a[href^="mailto:"]) strong::after { content: " por nuestro equipo en Palamós y en la Costa Brava — "; font-weight: 400; }
html[lang^="es"] .solandvolt-product-reassurance .sv-reassurance-item:has(a[href^="mailto:"]) a::after { content: "pedir presupuesto"; }
/* Zendure (912, 913, 914) : premiere ligne differente (livraison en Espagne uniquement) */
