html[lang^="es"] body.postid-913 .solandvolt-product-reassurance .sv-reassurance-item:first-child strong::before,
html[lang^="es"] body.postid-914 .solandvolt-product-reassurance .sv-reassurance-item:first-child strong::before { content: "\00a0 Envío gratuito"; }
html[lang^="es"] body.postid-912 .solandvolt-product-reassurance .sv-reassurance-item:first-child strong::after,
html[lang^="es"] body.postid-913 .solandvolt-product-reassurance .sv-reassurance-item:first-child strong::after,
html[lang^="es"] body.postid-914 .solandvolt-product-reassurance .sv-reassurance-item:first-child strong::after { content: " solo a España peninsular por ahora"; }

/* Sol & Volt 03/11 : descriptions courtes en espagnol de ?p=341 et ?p=339 (a retirer si traduites dans TranslatePress) */
